package com.bank.search;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SearchCompareDemo {

    private static final Logger log = Logger.getLogger(SearchCompareDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Sorted array of 16 account suffix numbers.
        int[] accounts = {2, 5, 8, 12, 17, 23, 30, 38, 45, 52, 60, 68, 77, 85, 92, 99};
        int target = 85;

        SearchComparator comparator = new SearchComparator();

        comparator.linearSearch(accounts, target);
        comparator.binarySearch(accounts, target);
    }
}

// ─── Would be in service/SearchComparator.java in a real project ───
class SearchComparator {

    private static final Logger log = Logger.getLogger(SearchComparator.class.getName());

    // Linear: check every element; works on unsorted data too.
    int linearSearch(int[] arr, int target) {
        int comparisons = 0;
        for (int i = 0; i < arr.length; i++) {
            comparisons++;
            if (arr[i] == target) {
                final int c = comparisons, idx = i;
                log.info(() -> "LINEAR found " + target + " at index " + idx
                        + " after " + c + " comparison(s)");
                return i;
            }
        }
        final int c = comparisons;
        log.info(() -> "LINEAR not found after " + c + " comparison(s)");
        return -1;
    }

    // Binary: halve the sorted range; requires sorted data.
    int binarySearch(int[] sorted, int target) {
        int left = 0, right = sorted.length - 1, comparisons = 0;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            comparisons++;
            if (sorted[mid] == target) {
                final int c = comparisons, idx = mid;
                log.info(() -> "BINARY found " + target + " at index " + idx
                        + " after " + c + " comparison(s)");
                return mid;
            } else if (sorted[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        final int c = comparisons;
        log.info(() -> "BINARY not found after " + c + " comparison(s)");
        return -1;
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
